async function main() {
  const all = [];
  for (let page = 1; page <= 100; page++) {
    const res: any = await tools.list_issues({ repo: "acme/cli", state: "open", page });
    let items: any = res;
    if (typeof items === "string") {
      try { items = JSON.parse(items); } catch { /* leave as-is */ }
    }
    if (!Array.isArray(items)) {
      items = items && (items.items || items.issues || items.data);
    }
    if (!Array.isArray(items)) {
      return { error: "unexpected list_issues shape", sample: JSON.stringify(res).slice(0, 800) };
    }
    if (items.length === 0) break;
    all.push(...items);
    if (items.length < 50) break;
  }

  const missingLabelsField = all.filter((i: any) => i.labels === undefined);
  if (missingLabelsField.length > 0) {
    return { error: "issues missing labels field", sample: JSON.stringify(missingLabelsField[0]).slice(0, 800) };
  }

  const seen = new Set<number>();
  const targets: number[] = [];
  for (const i of all) {
    const num = Number(i.number);
    if (seen.has(num)) continue;
    seen.add(num);
    if (Array.isArray(i.labels) && i.labels.length === 0) targets.push(num);
  }

  const results: any[] = [];
  for (const num of targets) {
    try {
      const r = await tools.add_label({ repo: "acme/cli", number: num, label: "needs-triage" });
      results.push({ number: num, ok: true, r: JSON.stringify(r).slice(0, 200) });
    } catch (e: any) {
      results.push({ number: num, ok: false, err: String(e && e.message || e) });
    }
  }

  return { totalOpen: seen.size, labeled: targets, results };
}

return await main();
